// Step 1: ask which robots the venue reports (read-only). Credentials come from the Node-RED environment, never from this file.
const base = env.get('MEKONIQ_BASE_URL'), venue = env.get('MEKONIQ_VENUE_ID'), token = env.get('MEKONIQ_TOKEN');
if (!base || !venue || !token) { node.error('MEKONIQ_BASE_URL, MEKONIQ_VENUE_ID and MEKONIQ_TOKEN must be set in the environment'); return null; }
msg.method = 'GET';
msg.url = base + '/v1/automation/venues/' + encodeURIComponent(venue) + '/events?kind=robot';
msg.headers = { Authorization: 'Bearer ' + token };
return msg;

// Remember the robots (with the age of the data) for the next step.
flow.set('robots', (msg.payload && msg.payload.records) || []);
msg.method = 'GET';
msg.url = env.get('MEKONIQ_BASE_URL') + '/v1/automation/venues/' + encodeURIComponent(env.get('MEKONIQ_VENUE_ID')) + '/events?kind=allocation';
msg.headers = { Authorization: 'Bearer ' + env.get('MEKONIQ_TOKEN') };
return msg;

// Fulfillment ready -> request ONE delivery per session. Explicit capability check first: no capable robot (trays, current map) means leave it to staff.
const venue = env.get('MEKONIQ_VENUE_ID'), mapRevision = env.get('MEKONIQ_MAP_REVISION');
const robots = (flow.get('robots') || []).filter(r => Number(r.state.trays) >= 1 && r.state.mapRevision === mapRevision && r.state.status !== 'offline' && r.state.driver !== undefined);
const groups = {};
for (const a of (msg.payload && msg.payload.records) || []) {
  if (a.state.status === 'reserved' && !a.state.missionId) (groups[a.state.sessionId] = groups[a.state.sessionId] || []).push(a.id);
}
const out = [], skipped = [];
for (const [groupId, ids] of Object.entries(groups)) {
  if (!robots.length) { skipped.push({ payload: { groupId, reason: 'NO_CAPABLE_ROBOT' } }); continue; }
  // The ids derive from the session, so a replayed poll or a restarted flow asks for the same mission, not another.
  const operationId = 'delivery-' + groupId;
  out.push({ operationId, payload: { type: 'Mission.Create', operationId, payload: { missionId: operationId, kind: 'delivery', allocationIds: ids.sort() } } });
}
return [out, skipped];

msg.method = 'POST';
msg.url = env.get('MEKONIQ_BASE_URL') + '/v1/automation/venues/' + encodeURIComponent(env.get('MEKONIQ_VENUE_ID')) + '/commands';
msg.headers = { Authorization: 'Bearer ' + env.get('MEKONIQ_TOKEN'), 'Content-Type': 'application/json' };
return msg;

// pending / unknown: keep the SAME operationId and ask again later. Never mint a new one.
const r = msg.payload || {};
if (r.status === 'pending' || r.status === 'unknown') {
  const tries = (msg.tries || 0) + 1;
  if (tries > 6) { node.warn('still ' + r.status + ' after ' + tries + ' checks: ' + msg.operationId); return [null, msg]; }
  msg.tries = tries;
  msg.method = 'GET';
  msg.url = env.get('MEKONIQ_BASE_URL') + '/v1/automation/venues/' + encodeURIComponent(env.get('MEKONIQ_VENUE_ID')) + '/commands/' + encodeURIComponent(msg.operationId);
  msg.headers = { Authorization: 'Bearer ' + env.get('MEKONIQ_TOKEN') };
  return [msg, null];
}
return [null, msg];
